(function(){
  function svgFor(name){
    if(FK_LINE[name]) return '<svg viewBox="0 0 24 24" class="ln" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+FKP(FK_LINE[name])+'</svg>';
    if(FK_ICONS_24[name]) return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+FK_ICONS_24[name]+'"/></svg>';
    const g = FK_ICONS[name];
    if(!g) return '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="5"/></svg>';
    return '<svg viewBox="0 -1536 '+g[0]+' 1792" aria-hidden="true"><path transform="scale(1,-1)" d="'+g[1]+'"/></svg>';
  }
  function fix(el){
    const name = (el.textContent||"").trim();
    if(!name || el.dataset.ic===name && el.firstElementChild) return;
    if(el.firstElementChild && el.firstElementChild.tagName && el.firstElementChild.tagName.toLowerCase()==="svg" && !name) return;
    el.dataset.ic = name;
    el.innerHTML = svgFor(name);
  }
  function scan(root){
    if(!root || root.nodeType!==1) return;
    if(root.classList && root.classList.contains("material-symbols-rounded")) fix(root);
    root.querySelectorAll && root.querySelectorAll(".material-symbols-rounded").forEach(fix);
  }
  window.fkIconSvg = svgFor;
  const start = ()=>{
    scan(document.body);
    new MutationObserver(muts=>{
      for(const m of muts){
        if(m.type==="characterData"){ const p=m.target.parentElement; if(p && p.classList.contains("material-symbols-rounded")) fix(p); continue; }
        if(m.target.nodeType===1 && m.target.classList.contains("material-symbols-rounded")) fix(m.target);
        m.addedNodes.forEach(scan);
      }
    }).observe(document.body, { childList:true, subtree:true, characterData:true });
  };
  if(document.body) start(); else document.addEventListener("DOMContentLoaded", start);
})();
